// Contrôles automatiques puis assemblage du pack (fichiers joints + récapitulatif).
const st = $('Sous-titres et repères').first().json;
const a = $('Analyse de la vidéo').first().json.output;
const r = $('Rédaction de la campagne').first().json.output;
const src = $('Préparer le fichier').first().json;
const sec = s => { const m = /^(\d{1,2}):(\d{2})$/.exec(String(s).trim()); return m ? +m[1] * 60 + +m[2] : NaN; };
const norm = s => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const transcription = norm(st.texte);
const ch = a.chapitres ?? [];
const nbMots = s => String(s).split(/\s+/).filter(Boolean).length;
const controles = [
  { label: 'Chapitres : premier à 00:00', ok: ch.length > 0 && sec(ch[0].debut) === 0 },
  { label: 'Chapitres : ordre chronologique et dans la durée', ok: ch.every((c, i) => !isNaN(sec(c.debut)) && sec(c.debut) <= st.duree_s && (i === 0 || sec(c.debut) > sec(ch[i - 1].debut))) },
  { label: 'Chapitres : 3 au minimum (exigence YouTube)', ok: ch.length >= 3 },
  { label: 'Citations reprises mot pour mot', ok: (a.citations ?? []).length > 0 && a.citations.every(c => transcription.includes(norm(c.texte))) },
  { label: 'Article : 400 à 600 mots', ok: nbMots(r.article_markdown) >= 380 && nbMots(r.article_markdown) <= 650, detail: nbMots(r.article_markdown) + ' mots' },
  { label: 'Meta description : 150 caractères au plus', ok: r.meta_description.length <= 155, detail: r.meta_description.length + ' car.' },
  { label: '3 posts LinkedIn', ok: (r.posts_linkedin ?? []).length === 3 },
  { label: 'Post court : 300 caractères au plus', ok: r.post_court.length <= 300, detail: r.post_court.length + ' car.' },
];
const aRevoir = controles.filter(c => !c.ok).map(c => c.label);
const chapitresYT = ch.map(c => c.debut + ' ' + c.titre).join('\n');
const campagne = [
  '# Campagne de contenus · ' + a.titre_video, '',
  '*Source : ' + src.nom_fichier + ' · ' + st.duree + ' · ' + st.mots + ' mots transcrits*', '',
  '## Vidéo', '', '**Titre :** ' + a.titre_video, '', '**Résumé :** ' + a.resume, '', '**Chapitres (description YouTube) :**', '', '```', chapitresYT, '```', '',
  '**Mots-clés :** ' + a.mots_cles.join(', '), '',
  '## Citations', '', ...a.citations.map(c => '- « ' + c.texte + ' » (' + c.horodatage + ')'), '',
  '## LinkedIn', '', ...r.posts_linkedin.flatMap((p, i) => ['### Post ' + (i + 1), '', p, '']),
  '## Instagram / Facebook', '', r.post_court, '',
  '## Newsletter', '', '**Objet :** ' + r.newsletter_objet, '', r.newsletter_texte, '',
  '## Article de blog', '', '**Meta description :** ' + r.meta_description, '', r.article_markdown, '',
].join('\n');
const fichier = async (txt, nom, type) => await this.helpers.prepareBinaryData(Buffer.from(txt, 'utf8'), nom, type);
const base = (src.nom_fichier || 'video').replace(/\.[^.]+$/, '');
return [{ json: { titre: a.titre_video, resume: a.resume, duree: st.duree, mots: st.mots, temps_transcription_s: st.temps_transcription_s,
    chapitres: ch, citations: a.citations, mots_cles: a.mots_cles, posts_linkedin: r.posts_linkedin, post_court: r.post_court,
    newsletter_objet: r.newsletter_objet, article_titre: r.article_titre, controles, a_revoir: aRevoir.join(' · ') },
  binary: {
    sous_titres_srt: await fichier(st.srt, base + '.srt', 'application/x-subrip'),
    sous_titres_vtt: await fichier(st.vtt, base + '.vtt', 'text/vtt'),
    article: await fichier(r.article_markdown, 'article-blog.md', 'text/markdown'),
    campagne: await fichier(campagne, 'campagne-complete.md', 'text/markdown'),
  } }];

// Un élément par fichier déposé.
const src = $('Ajouter des documents').first();
const fichiers = Object.values(src.binary ?? {});
if (!fichiers.length) throw new Error('Aucun fichier reçu.');
return fichiers.map(f => ({ json: { source: f.fileName, extension: (f.fileExtension || f.fileName.split('.').pop() || '').toLowerCase() }, binary: { data: f } }));

// PDF : texte extrait page par page.
return $input.all().map((it, i) => {
  const t = it.json.text;
  return { json: { source: $('Un élément par fichier').all().filter(x => x.json.extension === 'pdf')[i].json.source, format: 'pdf', pages: Array.isArray(t) ? t : [String(t ?? '')] } };
});

// Fichiers texte et Markdown : lecture directe.
const res = [];
for (let i = 0; i < $input.all().length; i++) {
  const it = $input.all()[i];
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  res.push({ json: { source: it.json.source, format: 'markdown', pages: [buf.toString('utf8')] } });
}
return res;

const MOTS_VIDES = new Set('le la les un une des de du et ou en au aux a ce ces cet cette est sont pour par sur dans avec sans que qui quoi quel quelle quels quelles ne pas plus se sa son ses leur leurs il elle ils elles on nous vous je tu y d l qu s c n m t j mon ma mes votre vos notre nos etre avoir fait faire peut doit comme si mais donc car tout tous toute toutes chaque entre apres avant'.split(' '));
const racine = w => /^\d/.test(w) || w.length < 5 ? w : w.replace(/(s|x)$/, '').replace(/e$/, '');
function termes(texte) {
  const t = String(texte).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const res = [];
  for (const [w] of t.matchAll(/[a-z0-9]+(?:[-.][a-z0-9]+)*/g)) {
    if (/[-.]/.test(w)) { res.push(w); for (const p of w.split(/[-.]/)) if (p.length > 1 && !MOTS_VIDES.has(p)) res.push(racine(p)); continue; }
    if (w.length > 1 && !MOTS_VIDES.has(w)) res.push(racine(w));
  }
  return res;
}
function fnv(s, graine = 0x811c9dc5) { let h = graine >>> 0; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h; }
function vecteurMots(texte, requete = false) {
  const tf = new Map();
  for (const w of termes(texte)) { const k = fnv(w); tf.set(k, (tf.get(k) || 0) + 1); }
  const L = [...tf.values()].reduce((a, b) => a + b, 0), k1 = 1.2, b = 0.75, moy = 90;
  const indices = [...tf.keys()];
  return { indices, values: indices.map(i => requete ? 1 : tf.get(i) * (k1 + 1) / (tf.get(i) + k1 * (1 - b + b * L / moy))) };
}
const empreinte = s => [0x811c9dc5, 0x12345678, 0x9e3779b9, 0x7f4a7c15].map(g => fnv(s, g).toString(16).padStart(8, '0')).join('');
const uuid = s => { const h = empreinte(s); return [h.slice(0, 8), h.slice(8, 12), h.slice(12, 16), h.slice(16, 20), h.slice(20, 32)].join('-'); };
// Découpage en passages : par section (titres Markdown ou titres numérotés des PDF), 1 000 caractères au plus, avec chevauchement.
const MAX = 1000;
function couper(bloc) {
  if (bloc.texte.length <= MAX) return [bloc];
  const paras = bloc.texte.split(/\n{1,}/).filter(p => p.trim());
  const res = []; let cur = [];
  for (const p of paras) {
    if (cur.join('\n').length + p.length > MAX && cur.length) { res.push({ ...bloc, texte: cur.join('\n') }); cur = [cur[cur.length - 1]]; }
    cur.push(p);
  }
  if (cur.length) res.push({ ...bloc, texte: cur.join('\n') });
  return res;
}
const docs = [];
for (const it of $input.all()) {
  const { source, format, pages } = it.json;
  const blocs = []; let titre = source.replace(/\.[^.]+$/, '').replace(/_/g, ' '), section = '', cur = [], page = 1;
  const vider = () => { const t = cur.join('\n').trim(); if (t.replace(/[*_#|\-\s]/g, '').length > 20) blocs.push({ section: section ? titre + ' › ' + section : titre, page: format === 'pdf' ? page : null, texte: t }); cur = []; };
  pages.forEach((txt, p) => {
    if (format === 'pdf') { vider(); page = p + 1; }
    const lignes = String(txt).split('\n');
    lignes.forEach((l, k) => {
      const md = format !== 'pdf' && /^(#{1,3})\s+(.*)/.exec(l);
      const num = format === 'pdf' && /^\d+\.\s+\S.{0,70}$/.test(l.trim()) && !/[.:;,]$/.test(l.trim());
      if (format === 'pdf' && p === 0 && k === 0 && l.trim()) { titre = l.trim(); return; }
      if (md) { vider(); if (md[1] === '#') titre = md[2].trim(); else section = md[2].trim(); return; }
      if (num) { vider(); section = l.trim(); return; }
      cur.push(l);
    });
  });
  vider();
  const passages = blocs.flatMap(couper).map((b, i) => ({ ...b, index: i }));
  const contenu = pages.join('\n');
  docs.push({ json: { source, titre, empreinte: empreinte(contenu), nb_passages: passages.length, passages } });
}
return docs;

// Compare chaque document à la version déjà indexée (empreinte du contenu).
const indexes = new Map(($('Versions déjà indexées').first().json.result?.points ?? []).map(p => [p.payload.source, p.payload.empreinte]));
return $('Découper en passages').all().map(d => {
  const ancien = indexes.get(d.json.source);
  const statut = !ancien ? 'nouveau' : ancien === d.json.empreinte ? 'inchangé' : 'mis à jour';
